        [ dct:conformsTo [ proc:ref <https://w3id.org/ogc/hosted/seadots/reef-aggregation-index/schema.json> ;
                    seadots:contentMediaType "application/json" ] ;
            dct:description "Per-taxon AF_i bindings." ;
