            dct:description "Sigmoid parameters L, k, t0 (months); evaluated to C_t for the equation." ;
            dct:title "Colonisation time factor" ;
            ogcapi-proc:additionalParameters [ seadots:parameters [ seadots:name "equationBinding" ;
